import math
from itertools import permutations

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_coolness_brute_force(n):
    """
    Checks coolness by iterating through all permutations. 
    Only suitable for very small n (e.g., n <= 8).
    """
    elements = list(range(1, n + 1))

    for p in permutations(elements):
        prefix_sums = []
        current_sum = 0
        is_valid = True
        for x in p:
            current_sum += x
            prefix_sums.append(current_sum)
            if is_perfect_square(current_sum):
                is_valid = False
                break

        if is_valid:
            return True
    return False

def check_coolness_backtracking(n):
    """
    Checks coolness using backtracking for potentially larger n.
    """

    # State: (current_sum, used_mask)
    # We use a recursive function to explore paths

    def solve(current_sum, used_mask, path_length):
        if path_length == n:
            return True

        for k in range(1, n + 1):
            # Check if k has been used
            if not (used_mask & (1 << (k - 1))):
                new_sum = current_sum + k

                # Check if the new prefix sum is a perfect square
                if not is_perfect_square(new_sum):
                    new_mask = used_mask | (1 << (k - 1))
                    if solve(new_sum, new_mask, path_length + 1):
                        return True
        return False

    # Start the search: sum=0, mask=0, length=0
    # We need to check the first step explicitly if we start at length 0, 
    # but the solver structure handles it if we iterate over k for the first step.
    return solve(0, 0, 0)

